WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY stock_qty NULLS LAST, id) AS latest_rank FROM products) ranked WHERE latest_rank = 1), kept AS (SELECT s.* FROM ranked s WHERE EXISTS (SELECT 1 FROM order_items ch WHERE ch.product_id = s.id AND ch.order_id = 38)), kept_keys AS (SELECT category FROM kept INTERSECT SELECT category FROM products WHERE cost > 270), verified AS (SELECT s.* FROM kept s INNER JOIN kept_keys k ON s.category = k.category), not_flagged AS (SELECT s.* FROM verified s WHERE EXISTS (SELECT 1 FROM order_items c WHERE c.product_id = s.id AND c.quantity >= 5)), with_windows AS (SELECT *, CORR(price, stock_qty) OVER (PARTITION BY category) AS corr_price_stock_qty, STDDEV_SAMP(cost) OVER (PARTITION BY category) AS category_stddev_samp_cost, STDDEV_SAMP(cost) OVER (PARTITION BY brand) AS brand_stddev_samp_cost, CUME_DIST() OVER (PARTITION BY category ORDER BY cost NULLS FIRST) AS cost_cume_dist, MIN(cost) OVER (PARTITION BY brand) AS brand_min_cost FROM not_flagged), cleaned AS (SELECT *, GREATEST(brand_stddev_samp_cost, latest_rank) AS greatest_brand_stddev_samp_cost_latest_rank FROM with_windows WHERE brand IS NOT NULL AND corr_price_stock_qty > 0.2), cleaned_products AS (SELECT *, CAST(latest_rank AS STRING) AS latest_rank_str FROM cleaned WHERE cost > 600), stats AS (SELECT brand, CASE WHEN cost_cume_dist >= 0.81 THEN 'LARGE' ELSE 'SMALL' END AS cost_cume_dist_tier, COUNT(*) AS num_rows, COUNT(DISTINCT brand) AS distinct_brands, SUM(price) FILTER (WHERE brand = 'Stark') AS stark_total_price, STDDEV_SAMP(price) AS price_stddev FROM cleaned_products GROUP BY GROUPING SETS ((brand, CASE WHEN cost_cume_dist >= 0.81 THEN 'LARGE' ELSE 'SMALL' END), (brand)) HAVING STDDEV_SAMP(price) > 0) SELECT brand, cost_cume_dist_tier, num_rows, stark_total_price, CASE WHEN brand RLIKE '^(Umbrella|Globex)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS brand_zone FROM stats ORDER BY stark_total_price DESC NULLS LAST
